css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .4); display: flex; align-items: center; justify-content: center; gap: calc(var(--loader-size) * .06); }
.loader span { width: calc(var(--loader-size) * .1); height: calc(var(--loader-size) * .1); border-radius: 50%; background: var(--accent); opacity: .3; animation: type calc(var(--loader-speed) * 1.2) ease-in-out infinite; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .18); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * .36); }
.loader i { width: calc(var(--loader-size) * .035); height: 68%; background: var(--accent-2); animation: blink calc(var(--loader-speed) * .9) step-end infinite; }
@keyframes type { 0%, 100% { opacity: .3; transform: translateY(0); } 50% { opacity: 1; transform: translateY(-24%); } }
@keyframes blink { 0%, 50% { opacity: 1; } 51%, 100% { opacity: 0; } }
